return {rwnpc01={id="rwnpc01",dsc="他穿着儒雅，曾经高中进士，如今在平安小镇里做教书先生。",sex="男",age=38,looks=20,showequip={},withCorpse=0},rwnpc02={id="rwnpc02",dsc="他似乎是某个富商的门客，常代富商开设擂台，以招贤纳士。",sex="男",age=40,looks=19,showequip={},withCorpse=0},rwnpc03={id="rwnpc03",dsc="观其衣饰，似非中原之人，而其肩之上竟趴着两只硕大的蜘蛛。",sex="男",age=28,looks=21,showequip={},withCorpse=0},rwnpc04={id="rwnpc04",dsc="他负手而立，看着神闲气定，气度很是不凡。",sex="男",age=45,looks=19,showequip={},withCorpse=0},rwnpc05={id="rwnpc05",dsc="他一袭白衣黑裤，长剑抱于怀中，相貌与身旁男子恰似一个模子所刻。",sex="男",age=24,looks=17,showequip={},withCorpse=0},rwnpc06={id="rwnpc06",dsc="他一袭黑衣白裤，长刀抱于怀中，相貌与身旁男子恰似一个模子所刻。",sex="男",age=24,looks=17,showequip={},withCorpse=0},rwnpc07={id="rwnpc07",dsc="他颇有些家产，素日最喜呼朋引伴，一起玩乐。",sex="男",age=27,looks=20,showequip={},withCorpse=0},rwnpc08={id="rwnpc08",dsc="一个技艺娴熟，手法精湛的老手艺人。",sex="男",age=65,looks=17,showequip={},withCorpse=0},rwnpc09={id="rwnpc09",dsc="她是天狼教的大师姐，她是魏师道诸多弟子中天赋最高的一人，据说她的练毒之术已不逊“毒师”，却也不知真假。",sex="女",age=29,looks=22,showequip={},withCorpse=0},rwnpc10={id="rwnpc10",dsc="他便是鸩羽山庄年轻一代的高手，鸩羽山庄庄主的唯一弟子，他年纪轻轻，武功造诣已是不凡。",sex="男",age=22,looks=24,showequip={},withCorpse=0},rwnpc11={id="rwnpc11",dsc="雪山寺年轻一代的代表人物，被方丈派遣至关外。",sex="男",age=25,looks=19,showequip={},withCorpse=0},rwnpc12={id="rwnpc12",dsc="他是伏龙山的堂主，他为人豁达大度，交得不少江湖好友，做事老练，颇得任天南赏识。",sex="男",age=35,looks=20,showequip={},withCorpse=0},rwnpc13={id="rwnpc13",dsc="他是拜日教长老，整日千金买醉，已不再过问教中事务。",sex="男",age=35,looks=20,showequip={},withCorpse=0},rwnpc14={id="rwnpc14",dsc="她便是这一代的万灵谷主，她身穿粉红纱裙，美艳不可方物，手脚都穿戴着金银饰器，稍一活动，金银就发出的清脆的碰撞声音，十分好听。",sex="女",age=17,looks=26,showequip={},withCorpse=0},rwnpc15={id="rwnpc15",dsc="万灵谷的护法弟子，身材魁梧，方面大耳。在教中转管招募教众，教授弟子们的入门功夫。",sex="男",age=60,looks=18,showequip={},withCorpse=0},rwnpc16={id="rwnpc16",dsc="幽冥教主的二弟子，但天赋不够而未能学成教主的独门武功。",sex="男",age=20,looks=25,showequip={},withCorpse=0},rwnpc17={id="rwnpc17",dsc="他是金牛武馆的一名教头。",sex="男",age=31,looks=18,showequip={},withCorpse=0},rwnpc18={id="rwnpc18",dsc="他是海鲸帮的一个小头目，长得十分瘦弱，似乎一吹就倒。",sex="男",age=29,looks=13,showequip={},withCorpse=0},rwnpc19={id="rwnpc19",dsc="明教五行旗的厚土旗旗主。",sex="男",age=45,looks=20,showequip={},withCorpse=0},rwnpc20={id="rwnpc20",dsc="他是唐门年轻一代的高手，江湖人称“唐七手”。",sex="男",age=20,looks=18,showequip={},withCorpse=0},rwnpc21={id="rwnpc21",dsc="她是虚渺宫的弟子，不爱习武，倒喜欢四处行商，总会带回来一些新鲜好玩的玩意。",sex="女",age=24,looks=21,showequip={},withCorpse=0},rwnpc22={id="rwnpc22",dsc="她生得娇小，幼时就被训练成永夜楼的杀手，因外表柔弱，常常能杀人于无形。楼中都道她是个孤儿，但又有不少人说她本是江湖名门，父母尚在人世。",sex="女",age=27,looks=21,showequip={},withCorpse=0},rwnpc23={id="rwnpc23",dsc="她是上官林之女，财神帮帮主。她智慧绝伦，以女流之躯经营庞大的财神帮，并开始开拓海外贸易。好收集奇珍异宝，富可敌国。武功习自其父，虽身手了得，但凡事都喜欢用金钱来解决，不喜动武。",sex="女",age=23,looks=26,showequip={},withCorpse=0},rwnpc24={id="rwnpc24",dsc="龙城山庄的侍从，慕容业最得意的手下，他眼如点墨，眉如远山，颔下有须，足显风流。",sex="男",age=32,looks=21,showequip={},withCorpse=0},rwnpc25={id="rwnpc25",dsc="龙千慧是问情宫的绝顶高手之一。她年少成名，年轻时美貌如花，又智计百出，加上出身名门，被江湖人尊称为大小姐。",sex="女",age=36,looks=30,showequip={},withCorpse=0},rwnpc26={id="rwnpc26",dsc="他一手持玉壶，一手执墨笔，既有些轻狂意气，又带着几分洒脱不羁。他看似是个寻常书生，实则武学承袭多脉，深不可测。平日里他从不以武为傲，只称自己是个目不识丁的说书人。江湖中大多传奇话本，都出自他的手笔。",sex="男",age=38,looks=28,showequip={},withCorpse=0},rwnpc27={id="rwnpc27",dsc="祝雨同是蓬莱岛的名宿，他常年住在落英湾。他武功高强，但因为极少在江湖上走动，所以听说过他名字的人不多。",sex="男",age=35,looks=24,showequip={},withCorpse=0},rwnpc28={id="rwnpc28",dsc="沈丽娘是蓬莱岛高手，同时还与祝雨同青梅竹马，十年前结为夫妻。二人夫唱妇随伉俪情深，羡煞旁人。",sex="女",age=32,looks=27,showequip={},withCorpse=0},rwnpc29={id="rwnpc29",sex="男",age=40,looks=15,showequip={},withCorpse=0},rwnpc30={id="rwnpc30",sex="男",age=27,looks=20,showequip={},withCorpse=0},rwnpc31={id="rwnpc31",dsc="他粗眉大眼，长的有些英雄气概，在全真教第三代弟子中算得上年轻有为。",sex="男",age=25,looks=20,showequip={},withCorpse=0},rwnpc32={id="rwnpc32",dsc="这是昆仑派弟子温笑笑，整天就喜欢玩耍，不爱干正事。",sex="男",age=20,looks=23,showequip={},withCorpse=0},rwnpc33={id="rwnpc33",dsc="乃是崆峒掌门的弟子，武功不凡。",sex="男",age=22,looks=24,showequip={},withCorpse=0},rwnpc34={id="rwnpc34",dsc="莫灵儿是华山掌门莫天雄的独生女儿。",sex="女",age=22,looks=20,showequip={},withCorpse=0},rwnpc35={id="rwnpc35",dsc="峨眉“三剑”之一，清丽秀雅，姿容甚美。",sex="女",age=20,looks=25,showequip={},withCorpse=0},rwnpc36={id="rwnpc36",dsc="落月山庄的一名弟子。目若秋水，风度翩翩，笑容让人捉摸不定。",sex="男",age=20,looks=23,showequip={},withCorpse=0},rwnpc37={id="rwnpc37",dsc="官府弟子，凌云的兄长，和明宗宝、齐天关系十分要好。",sex="男",age=30,looks=20,showequip={},withCorpse=0},rwnpc38={id="rwnpc38",sex="男",age=20,looks=20,showequip={},withCorpse=0},rwnpc39={id="rwnpc39",dsc="天龙寺的一名僧人。",sex="男",age=20,looks=18,showequip={},withCorpse=0},rwnpc40={id="rwnpc40",dsc="天龙寺的一名僧人。",sex="男",age=20,looks=18,showequip={},withCorpse=0},rwnpc41={id="rwnpc41",dsc="他是马三德的独子，自幼顽皮，跟他父亲一样不喜欢读书，整日从私塾里逃出来胡闹，自称天下没人能够管住他。",sex="男",age=10,looks=20,showequip={},withCorpse=0},rwnpc42={id="rwnpc42",dsc="一只大白狗，不断地摇着尾巴，和大黄的关系很好。",sex="野兽",age=0,looks=0,showequip={},withCorpse=0},rwnpc43={id="rwnpc43",dsc="一只大黄狗，不断地摇着尾巴，见到人都会跑上去蹭两圈，十分可爱。",sex="野兽",age=0,looks=0,showequip={},withCorpse=0},rwnpc44={id="rwnpc44",dsc="她个头要比同龄孩童还要小巧些，走起路来摇摇晃晃，手中拿着一个冰糖葫芦，笑嘻嘻的望着你。",sex="女",age=10,looks=18,showequip={},withCorpse=0},rwnpc45={id="rwnpc45",dsc="他是镇里的小孩，瞧着虎头虎脑，煞是可爱。",sex="男",age=10,looks=20,showequip={},withCorpse=0},rwnpc46={id="rwnpc46",dsc="他是平安小镇的居民，有几分小聪明，去年做了点小生意赚了不少钱，在镇中出了名的怕老婆，常常被罚跪搓衣板。",sex="男",age=33,looks=19,showequip={},withCorpse=0},rwnpc47={id="rwnpc47",dsc="他是平安小镇的居民，本是个教书先生，据说年轻时曾经中过举人，但是真是假不得而知。",sex="男",age=55,looks=20,showequip={},withCorpse=0},rwnpc48={id="rwnpc48",dsc="似乎是被小镇的热闹给吸引来的。",sex="男",age=30,looks=20,showequip={},withCorpse=0},rwnpc49={id="rwnpc49",dsc="其貌不修边幅，方一靠近，便有浓烈酒气扑鼻而来。",sex="男",age=30,looks=21,showequip={},withCorpse=0},rwnpc50={id="rwnpc50",dsc="他穿着粗布麻衣，形销骨立。",sex="男",age=15,looks=15,showequip={},withCorpse=0},rwnpc51={id="rwnpc51",dsc="他看着不过十岁，虽衣衫破旧，然拾掇得尚算齐整。",sex="男",age=10,looks=15,showequip={},withCorpse=0},rwnpc52={id="rwnpc52",dsc="她看着不过十岁，虽衣衫破旧，然拾掇得尚算齐整。",sex="女",age=10,looks=17,showequip={},withCorpse=0},rwnpc53={id="rwnpc53",dsc="其衣衫虽破旧不堪，仍不失儒雅之态。",sex="男",age=35,looks=20,showequip={},withCorpse=0},rwnpc54={id="rwnpc54",dsc="他是镇中恶名昭著的恶霸，常横行无忌。",sex="男",age=27,looks=18,showequip={},withCorpse=0},rwnpc55={id="rwnpc55",dsc="他是镇中恶名昭著的恶霸，常横行无忌。",sex="男",age=27,looks=14,showequip={},withCorpse=0},rwnpc56={id="rwnpc56",dsc="他是镇中恶名昭著的恶霸，常横行无忌。",sex="男",age=27,looks=13,showequip={},withCorpse=0},rwnpc57={id="rwnpc57",dsc="他看起来是个江湖游侠，头戴斗笠，声气粗豪。",sex="男",age=50,looks=19,showequip={},withCorpse=0},rwnpc58={id="rwnpc58",dsc="她是平安小镇的居民，在家中排行第二，早年嫁给了一个江湖浪人，后夫君远走江湖再未归来。",sex="女",age=44,looks=18,showequip={},withCorpse=0},rwnpc59={id="rwnpc59",dsc="他为人十分老实，少年时本打算考取功名，可惜家道中落，于是学着别人落草为寇，但因为十分老实被赶出了山寨，如今耕田过日子倒也自在。",sex="男",age=29,looks=16,showequip={},withCorpse=0},rwnpc60={id="rwnpc60",dsc="他看起来风尘仆仆，状态有些草木皆兵。",sex="男",age=40,looks=18,showequip={},withCorpse=0},rwnpc61={id="rwnpc61",sex="男",age=30,looks=18,showequip={},withCorpse=0},rwnpc62={id="rwnpc62",dsc="她穿着宽松大袍，带着一个白色的面具，看不出样貌。",sex="女",age=23,looks=10,showequip={},withCorpse=0},bsnpc01={id="bsnpc01",dsc="她身着破旧的粗布衣，身上挂着用线绳穿好的十多双大大小小的草鞋、布鞋。",sex="女",age=45,looks=18,showequip={},withCorpse=0},bsnpc02={id="bsnpc02",dsc="他是卖杂货的商贩，并不常出现在此处。",sex="男",age=32,looks=18,showequip={},withCorpse=0},bsnpc03={id="bsnpc03",dsc="他一副书生模样，但手中却拿着一个沉重的流星锤，虽是有模有样的耍着，但因气力不足，下盘紊乱，常常将流星锤砸入四周的石板，引得周围人群纷纷避让。",sex="男",age=17,looks=20,showequip={},withCorpse=0},bsnpc04={id="bsnpc04",dsc="一个专门制作葱包桧的小贩。",sex="男",age=45,looks=17,showequip={},withCorpse=0},bsnpc05={id="bsnpc05",sex="男",age=45,looks=17,showequip={},withCorpse=0},bsnpc06={id="bsnpc06",dsc="他梳着一个长长的小辫，手上拿着一把桃木短剑，面目严肃，颇有几分“大侠”的样子。",sex="男",age=11,looks=19,showequip={},withCorpse=0},bsnpc07={id="bsnpc07",dsc="一个专卖桂花板栗糕的小贩。",sex="男",age=45,looks=17,showequip={},withCorpse=0},bsnpc08={id="bsnpc08",dsc="他是平安小镇的居民，身穿粗布长衣，手中拿着一个鸟笼。鸟笼里关着一只翠鸟，毛色翠兰，十分夺目。",sex="男",age=35,looks=16,showequip={},withCorpse=0},bsnpc09={id="bsnpc09",dsc="一只花白小猫，卷卧在地，不时伸下懒腰，叫唤几声。",sex="野兽",age=0,looks=0,showequip={},withCorpse=0},bsnpc10={id="bsnpc10",dsc="他坐在轿子里，撩开帘子看向外面。这人眉目如画，青丝如瀑，搭在帘子上的手指白皙修长，戴着一枚白玉戒指。",sex="男",age=21,looks=24,showequip={},withCorpse=0},bsnpc11={id="bsnpc11",dsc="白衣男子轿子旁的护卫。",sex="男",age=21,looks=21,showequip={},withCorpse=0},bsnpc12={id="bsnpc12",dsc="一个专门制作麻球的小贩。",sex="男",age=45,looks=17,showequip={},withCorpse=0},bsnpc13={id="bsnpc13",dsc="他时常喝得酩酊大醉，听说多年前也曾是浪荡江湖的剑客，后来不知为何埋剑藏名隐居于平安小镇。",sex="男",age=45,looks=20,showequip={},withCorpse=0},bsnpc14={id="bsnpc14",dsc="他是平安小镇的糖贩，家中养了无数蜜蜂，做出的糖极为甜蜜。他为人亲和，时常会把自己做的各色糖果赠予镇中孩童。",sex="男",age=32,looks=17,showequip={},withCorpse=0},bsnpc15={id="bsnpc15",dsc="他穿了一身黑色劲装，眼神灵动，浑身充满了少年人才有的活力。",sex="男",age=23,looks=23,showequip={},withCorpse=0},bsnpc16={id="bsnpc16",dsc="她是平安小镇的居民，父母常年在外，由祖母一手带大，十分懂事。",sex="女",age=10,looks=18,showequip={},withCorpse=0},bsnpc17={id="bsnpc17",dsc="他祖上曾是名扬江湖的大侠，多年前偶然路过平安小镇，故在此安家，不涉江湖事多年。",sex="男",age=45,looks=19,showequip={},withCorpse=0},bsnpc18={id="bsnpc18",dsc="她是平安小镇的居民，听闻早年逃荒而来，她的青梅竹马则于半道饿死，致使其一生未嫁。",sex="女",age=56,looks=18,showequip={},withCorpse=0},bsnpc19={id="bsnpc19",dsc="他身着破烂衣衫，不知从何而来，一会儿声称自己是“八指神丐”，一会儿又说自己是苏乞儿之徒。他手中端着的一个缺口白碗，据说是祖传宝物。",sex="男",age=17,looks=15,showequip={},withCorpse=0},bsnpc20={id="bsnpc20",dsc="他闲散于江湖，自嘲自己学武不专，所以号“半武”。在平安小镇隐居多年，少有人看到他出招练武，只当是个寻常人，但其内力似乎深不可测。",sex="男",age=45,looks=25,showequip={},withCorpse=0},bsnpc21={id="bsnpc21",dsc="浑身黝黑的打铁匠。",sex="男",age=45,looks=19,showequip={},withCorpse=0},bsnpc22={id="bsnpc22",dsc="她走起路来颇有几分“婀娜”之感，听闻早年流落风尘被一名侠客所救，如今在这平安小镇里安度余生。",sex="女",age=43,looks=18,showequip={},withCorpse=0},bsnpc23={id="bsnpc23",dsc="他是村中顽童，父亲是个马商，故小名叫“马儿”，日子久了大家反而忘记了他原本的名字。他跨着一个竹马，正学着戏文的那些江湖豪杰“行侠仗义”。",sex="男",age=10,looks=17,showequip={},withCorpse=0},bsnpc24={id="bsnpc24",dsc="他是菜来饭馆的小二。",sex="男",age=17,looks=20,showequip={},withCorpse=0},bsnpc25={id="bsnpc25",dsc="他是一个马贩，常年在外奔波，不久前在去往西域时被沙匪所劫，幸得江湖中的侠客路过救了他一命。可惜他身受重伤，落下了病根，自此不宜远行。",sex="男",age=35,looks=17,showequip={},withCorpse=0},bsnpc26={id="bsnpc26",dsc="他手上拿着一把钉耙，听说自小就想成为游走江湖的大侠，可惜祖上代代务农，故其父不允其出门学艺。",sex="男",age=21,looks=19,showequip={},withCorpse=0},bsnpc27={id="bsnpc27",dsc="他是平安小镇的居民，曾是附近县里头的师爷，公正无私，协助官老爷处理了不少冤案。在镇中颇有几分声望，受到邻里的尊重。",sex="男",age=55,looks=17,showequip={},withCorpse=0},bsnpc28={id="bsnpc28",dsc="他是平安小镇的普通居民，平日里都在田间务农，虽然大字不识几个，却喜欢观摩镇中老者下棋，故而看上去略给人几分聪慧之感。",sex="男",age=24,looks=17,showequip={},withCorpse=0},bsnpc29={id="bsnpc29",dsc="一头黄牛，脖子上挂着一个巨大的铃铛。鼻孔吐着热气，嘴中咀嚼着反刍上来的草料。",sex="野兽",age=0,looks=0,showequip={},withCorpse=0},bsnpc30={id="bsnpc30",dsc="他是一个江湖侠客，身后背着一把极为沉重的巨剑，名为“战戈”。他脸上有一道疤痕，不知是从何而来，下巴处许久没有打理的胡渣让他看上去十分沧桑。",sex="男",age=45,looks=23,showequip={},withCorpse=0},bsnpc31={id="bsnpc31",dsc="他是平安小镇的居民，曾在武馆学艺多年，如今在镇中教习些拳脚。",sex="男",age=27,looks=19,showequip={},withCorpse=0},bsnpc32={id="bsnpc32",dsc="他穿着朴素，此时正在安排一些苦力搬运货物。",sex="男",age=35,looks=20,showequip={},withCorpse=0},bsnpc33={id="bsnpc33",dsc="早年靠车马发家，如今生意遍布大江南北。他身材清瘦，两眼微凹，腰间挂着一把老旧的长鞭，据说是年少时所用。",sex="男",age=45,looks=17,showequip={},withCorpse=0}}00000